<script setup lang="ts">
import { ref } from 'vue'; import { ElMessage } from 'element-plus'; import request from '@/utils/request'; import type { ApiResponse } from '@/types'
interface Question { id:number; stem:string; question_type:string; options:Record<string,string>; score:number }
const examId=ref<number>(); const attemptId=ref<number>(); const questions=ref<Question[]>([]); const answers=ref<Record<number,string[]>>({}); const result=ref<any>();
async function start(){ if(!examId.value)return; try{const {data}=await request.post<ApiResponse<any>>(`/exams/${examId.value}/start`); attemptId.value=data.data.attempt.id; questions.value=data.data.questions}catch(e:any){ElMessage.error(e.response?.data?.message||'无法开始考试')} }
async function submit(){ if(!examId.value)return; const payload={idempotency_key:crypto.randomUUID(),answers:questions.value.map(q=>({question_id:q.id,selected_answers:answers.value[q.id]||[]}))}; const {data}=await request.post<ApiResponse<any>>(`/exams/${examId.value}/submit`,payload); result.value=data.data; ElMessage.success('提交成功，已自动评分') }
</script>
<template><section class="page"><header class="page-header"><div><p class="eyebrow">EXAM CENTER</p><h1>考试中心</h1><p>答卷提交具备幂等保护，你的成绩只会生成一次。</p></div><div class="inline-action"><el-input-number v-model="examId" :min="1" placeholder="考试 ID"/><el-button type="primary" @click="start">开始考试</el-button></div></header><div v-if="questions.length" class="exam-paper"><article v-for="(q,index) in questions" :key="q.id"><h3>{{ index+1 }}. {{ q.stem }} <small>{{ q.score }} 分</small></h3><el-checkbox-group v-if="q.question_type==='multiple'" v-model="answers[q.id]"><el-checkbox v-for="(label,key) in q.options" :key="key" :value="key">{{ key }}. {{ label }}</el-checkbox></el-checkbox-group><el-radio-group v-else :model-value="answers[q.id]?.[0]" @change="(value: string | number | boolean | undefined)=>answers[q.id]=[String(value)]"><el-radio v-for="(label,key) in q.options" :key="key" :value="key">{{ key }}. {{ label }}</el-radio></el-radio-group></article><el-button type="primary" size="large" @click="submit">提交答卷</el-button></div><div v-if="result" class="result-card"><span>本次得分</span><strong>{{ result.objective_score }} / {{ result.total_score }}</strong><p>评分完成，错题已同步到错题本。</p></div><el-empty v-if="!questions.length&&!result" description="输入考试 ID 开始答题" /></section></template>
